// ═══ BUG: while(flag) never terminates ═══
class BrokenService {
    boolean running = true;  // NOT volatile!

    void processLoop() {
        while (running) {  // JIT may hoist: if (running) while(true) { ... }
            doWork();
        }
        // This line is NEVER reached!
    }

    void stop() {
        running = false;  // Written to main memory, but reader never checks!
    }
}
// JIT optimization (legal under JMM):
// Before: while (running) { doWork(); }
// After:  boolean cached = running;  // read ONCE
//         while (cached) { doWork(); }  // infinite!
// The JIT sees: running is never modified in the loop body
// → safe to cache in register → HOISTED read

// ═══ FIX: volatile prevents hoisting ═══
class FixedService {
    volatile boolean running = true;  // volatile!

    void processLoop() {
        while (running) {  // volatile read EVERY iteration → main memory!
            doWork();
        }
        // Reached when another thread sets running = false!
    }

    void stop() {
        running = false;  // volatile write → main memory + cache invalidation!
    }
}

// ═══ WHY JIT is allowed to do this ═══
// Java Memory Model (JMM): without volatile/synchronized, the JVM is NOT
// required to guarantee visibility between threads. The JIT compiler can:
// 1. Cache variables in CPU registers (avoid memory reads)
// 2. Reorder instructions (if no data dependency within the thread)
// 3. Hoist reads out of loops (if the variable isn't modified in the loop)
// volatile creates a "memory barrier" → prevents these optimizations.

// ═══ ALTERNATIVE FIX: synchronized ═══
class SyncService {
    boolean running = true;

    void processLoop() {
        while (isRunning()) {  // synchronized read every iteration
            doWork();
        }
    }

    synchronized boolean isRunning() { return running; }  // memory barrier!
    synchronized void stop() { running = false; }
}
// Works but SLOWER — monitor lock overhead on every iteration!
// volatile is much cheaper for simple flag reads.
```

