// ─── File: src/test/java/com/bank/hoisting/FlagHoistingTest.java ───
package com.bank.hoisting;

import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class FlagHoistingTest {

    // ═══ VOLATILE FLAG: terminates reliably ═══
    static class VolatileService {
        volatile boolean running = true;
        AtomicInteger iterations = new AtomicInteger(0);

        void processLoop() {
            while (running) {
                iterations.incrementAndGet();
                Thread.yield();
            }
        }

        void stop() { running = false; }
    }

    @Test
    void volatileFlag_terminatesReliably() throws InterruptedException {
        VolatileService service = new VolatileService();
        Thread worker = new Thread(service::processLoop);
        worker.start();

        Thread.sleep(100);  // let it run some iterations
        assertThat(service.iterations.get()).isGreaterThan(0);

        service.stop();  // volatile write!
        worker.join(2000);  // should terminate within 2s

        assertThat(worker.isAlive()).isFalse();  // terminated!
        System.out.println("Iterations before stop: " + service.iterations.get());
    }

    // ═══ NON-VOLATILE FLAG: may not terminate (JIT-dependent) ═══
    // NOTE: This test demonstrates the concept but may not reliably reproduce
    // the bug in all JVMs/modes because JIT optimization timing varies.
    static class NonVolatileService {
        boolean running = true;  // NOT volatile!
        AtomicInteger iterations = new AtomicInteger(0);

        void processLoop() {
            while (running) {  // JIT MAY hoist this read!
                iterations.incrementAndGet();
                // No memory barrier in loop → JIT may cache 'running'
            }
        }

        void stop() { running = false; }
    }

    @Test
    void nonVolatileFlag_mayNotTerminate() throws InterruptedException {
        NonVolatileService service = new NonVolatileService();
        Thread worker = new Thread(service::processLoop);
        worker.start();

        Thread.sleep(200);  // give JIT time to compile and optimize
        service.stop();

        worker.join(3000);  // wait up to 3 seconds

        if (worker.isAlive()) {
            System.out.println("BUG REPRODUCED! Thread didn't stop (JIT cached the flag).");
            worker.interrupt();  // force cleanup
            worker.join(1000);
        } else {
            System.out.println("Thread stopped (JIT didn't hoist in this run — timing-dependent).");
        }
    }

    // ═══ Multiple threads all see volatile flag change ═══
    @Test
    void multipleWorkers_allSeeVolatileStop() throws InterruptedException {
        VolatileService service = new VolatileService();
        Thread[] workers = new Thread[10];

        for (int i = 0; i < workers.length; i++) {
            workers[i] = new Thread(service::processLoop);
            workers[i].start();
        }

        Thread.sleep(100);
        service.stop();  // ONE volatile write

        for (Thread w : workers) {
            w.join(2000);
            assertThat(w.isAlive()).isFalse();  // ALL stopped!
        }
    }
}
